        buf = buf * 64 + v
        bits += 6
        if bits >= 8 then
            bits -= 8
            bytes[#bytes + 1] = math.floor(buf / (2 ^ bits)) % 256
            buf = buf % (2 ^ bits)
        end
    end
end

